def validate_sku(value):
    if not re.fullmatch(r"[A-Z]{3}-\d{4}", value):
        raise ValidationError("Use the format ABC-1234.")

class ProductForm(forms.ModelForm):
    sku = forms.CharField(validators=[validate_sku])

    class Meta:
        model = Product
        fields = ["sku", "name", "price"]

    def clean(self):
        cleaned = super().clean()
        if cleaned.get("price", 0) < 0:
            self.add_error("price", "Price cannot be negative.")
        return cleaned

