from django.http import FileResponse, StreamingHttpResponse

def export_orders(request):
    def rows():
        yield "id,customer,total\n"
        for order in Order.objects.filter(owner=request.user).iterator(chunk_size=500):
            yield f"{order.pk},{order.customer_id},{order.total}\n"

    response = StreamingHttpResponse(rows(), content_type="text/csv")
    response["Content-Disposition"] = 'attachment; filename="orders.csv"'
    return response

def download_invoice(request, pk):
    invoice = get_object_or_404(Invoice, pk=pk, owner=request.user)
    return FileResponse(invoice.file.open("rb"), as_attachment=True)

